import type { SystemStyleObject } from '@chakra-ui/react';

/**
 * Recipe for the touch-only PDP/card image position indicator — a 1px hairline strip, one
 * segment per image, the current position picked out by colour. Figma node 40002536:7957
 * ("Slide indicator"). Geometry AND colour are now both confirmed directly against the real
 * component (via `get_design_context` on three separate variants — 40002536:7956 (Qty=8,
 * selected=1), 40002536:7947 (Qty=5, selected=1), 40002536:7954 (Qty=5, selected=2) — chosen to
 * rule out any positional/count-dependent difference, and there is none): no inter-segment gap
 * (`flex items-center`, no gap class), equal-width segments (`flex-[1_0_0]`, an exact match for
 * this file's own `flex: '1 0 0'` below), and the active segment always painted with Figma's
 * `border/focus` token, every other segment with `border/secondary` — regardless of which index
 * is selected. `--zimm-scale-025` (1px height) was already correct from Step 1.
 *
 * Two parts:
 *   - `root` — the full-width flex strip, exactly `--zimm-scale-025` (1px) tall.
 *   - `dot` — one equal-width segment per image (despite the part name, this renders as a
 *     rectangle in a hairline, not a circular dot — the name matches this component's
 *     already-agreed contract, not a literal shape description).
 */
export const ZimmSlideIndicator = {
  parts: ['root', 'dot'],

  baseStyle: ({ isActive }: { isActive?: boolean }): Record<string, SystemStyleObject> => ({
    root: {
      display: 'flex',
      // Fluid, not a fixed Figma px width — matches the product card's own "fluid, not 288px"
      // rule: this strip always spans whatever width its image parent gives it, rather than
      // the specific 159.11px/99.44px bounding boxes the two sampled Figma variants happened
      // to measure at their own artboard widths.
      width: '100%',
      height: 'var(--zimm-scale-025)', // 1px, confirmed correct since Step 1.
      // Confirmed no gap: Figma's own `flex items-center` has no gap class — segments are
      // genuinely flush-adjacent, not merely left at a default pending confirmation.
      gap: 0,
    },

    dot: {
      // Confirmed exact match: Figma's own `flex-[1_0_0]` on every segment, regardless of count
      // or which one is active.
      flex: '1 0 0',
      height: '100%',
      // Both previously read from the wrong semantic alias — `--zimm-color-bg-05` and
      // `--zimm-color-opacity-40` happened to LOOK plausible (the active one even resolves to
      // the identical hex, since bg-05 and border-focus both trace to the same grey/900
      // primitive) but were never actually confirmed against the design, per this file's own
      // prior comment. Confirmed via `get_design_context`: the active segment's colour matches
      // Figma's `border/focus` token; every other segment matches `border/secondary` — a flat,
      // opaque light grey, notably lighter than the semi-transparent overlay `opacity-40`
      // previously produced. The active branch below reads `--zimm-color-bg-05`, not
      // `--zimm-color-border-focus` — a `border.*` alias is the wrong token *category* for a
      // `background` CSS property even though both resolve to the identical grey/900 hex (see
      // `foundation/colour.ts`); `border.secondary` has no `background.*` counterpart to swap
      // to, so the inactive branch keeps referencing it directly. Both remain
      // already-registered tokens, not new ones.
      background: isActive ? 'var(--zimm-color-bg-05)' : 'var(--zimm-color-border-secondary)',
    },
  }),
};

