import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen } from '@testing-library/react';
import { IntlProvider } from 'react-intl';
import { ZimmSlideIndicator } from './index';

// The recipe's actual colour/geometry values aren't relevant to this component's own contract
// (segment count, which one is active, accessibility) — mock the same flat-parts shape the
// zimmColourSwatchGroup test uses so no real Chakra theme is needed.
vi.mock('@chakra-ui/react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
  return {
    ...actual,
    useMultiStyleConfig: () => ({ root: {}, dot: {} }),
  };
});

const wrap = (ui: React.ReactElement) =>
  render(
    <IntlProvider locale="en" defaultLocale="en">
      {ui}
    </IntlProvider>,
  );

const segments = (container: HTMLElement) => Array.from(container.querySelectorAll('[aria-hidden="true"]'));
const activeSegments = (container: HTMLElement) => container.querySelectorAll('[data-active="true"]');

describe('ZimmSlideIndicator — segment count', () => {
  test('renders exactly 5 segments for count=5', () => {
    const { container } = wrap(<ZimmSlideIndicator count={5} activeIndex={0} />);
    expect(segments(container)).toHaveLength(5);
  });

  test('renders exactly 8 segments for count=8', () => {
    const { container } = wrap(<ZimmSlideIndicator count={8} activeIndex={0} />);
    expect(segments(container)).toHaveLength(8);
  });
});

describe('ZimmSlideIndicator — exactly one active segment', () => {
  test('marks the first segment active when activeIndex=0', () => {
    const { container } = wrap(<ZimmSlideIndicator count={5} activeIndex={0} />);
    const active = activeSegments(container);
    expect(active).toHaveLength(1);
    expect(segments(container).indexOf(active[0])).toBe(0);
  });

  test('marks the middle segment active', () => {
    const { container } = wrap(<ZimmSlideIndicator count={5} activeIndex={2} />);
    const active = activeSegments(container);
    expect(active).toHaveLength(1);
    expect(segments(container).indexOf(active[0])).toBe(2);
  });

  test('marks the last segment active when activeIndex=count-1', () => {
    const { container } = wrap(<ZimmSlideIndicator count={5} activeIndex={4} />);
    const active = activeSegments(container);
    expect(active).toHaveLength(1);
    expect(segments(container).indexOf(active[0])).toBe(4);
  });
});

describe('ZimmSlideIndicator — out-of-range activeIndex clamps rather than throwing', () => {
  test('activeIndex=-1 clamps to the first segment', () => {
    const { container } = wrap(<ZimmSlideIndicator count={5} activeIndex={-1} />);
    const active = activeSegments(container);
    expect(active).toHaveLength(1);
    expect(segments(container).indexOf(active[0])).toBe(0);
  });

  test('activeIndex=count (one past the end) clamps to the last segment', () => {
    const { container } = wrap(<ZimmSlideIndicator count={5} activeIndex={5} />);
    const active = activeSegments(container);
    expect(active).toHaveLength(1);
    expect(segments(container).indexOf(active[0])).toBe(4);
  });
});

describe('ZimmSlideIndicator — count <= 1 renders nothing', () => {
  test('count=0 renders nothing', () => {
    const { container } = wrap(<ZimmSlideIndicator count={0} activeIndex={0} />);
    expect(container.firstChild).toBeNull();
  });

  test('count=1 renders nothing', () => {
    const { container } = wrap(<ZimmSlideIndicator count={1} activeIndex={0} />);
    expect(container.firstChild).toBeNull();
  });
});

describe('ZimmSlideIndicator — accessibility (sole position signal on touch, SFCC-236)', () => {
  test('the root group is not aria-hidden', () => {
    wrap(<ZimmSlideIndicator count={5} activeIndex={1} />);
    const root = screen.getByRole('group');
    expect(root).not.toHaveAttribute('aria-hidden', 'true');
  });

  test('the root exposes the current position as its accessible name', () => {
    wrap(<ZimmSlideIndicator count={5} activeIndex={1} />);
    expect(screen.getByRole('group', { name: 'Image 2 of 5' })).toBeInTheDocument();
  });

  test('the accessible name reflects a clamped out-of-range activeIndex', () => {
    wrap(<ZimmSlideIndicator count={5} activeIndex={-1} />);
    expect(screen.getByRole('group', { name: 'Image 1 of 5' })).toBeInTheDocument();
  });
});

