import type { SystemStyleObject } from '@chakra-ui/react';

/**
 * Recipe for the PDP size-chip group. Two mutually-exclusive root renders, matching the two
 * "Type" variants of the size-chip Figma component set (node 40003066:34868):
 *   - `radiogroup` — the multi-size row (the default Type, 208x28 in Figma) — lays out
 *     ZimmSizeChip atoms in a row; each chip's own fill/border/focus styling stays in the
 *     sibling ZimmSizeChip atom's own recipe, this part is layout only.
 *   - `oneSize` — the single non-interactive label shown when only one size is offered (the
 *     other Type, 65x28 in Figma) — a genuinely different, non-interactive component, not a
 *     radiogroup with one item. Renders as a bordered box, the same visual language as the
 *     real interactive chips, just non-interactive — confirmed via `get_design_context` on
 *     node 40003066:34866 ("Type=One Size").
 */
export const ZimmSizeChipGroup = {
  parts: ['radiogroup', 'oneSize'],
  baseStyle: (): Record<string, SystemStyleObject> => ({
    radiogroup: {
      display: 'flex',
      alignItems: 'center',
      // `justifyContent: 'space-between'`, not a `gap` value: confirmed directly against the
      // real composed instance (`get_design_context` on node 40002163:41459, the PLP/PDP Hover
      // card) — the SizeSelector row is `flex items-center justify-between w-[208px]`, spreading
      // however many chips exist evenly across the card's full content width, with no gap
      // declared alongside it. This was previously left undeclared entirely ("no inter-chip gap
      // value confirmed") pending that exact measurement, which rendered every chip flush against
      // its neighbour with zero spacing — confirmed live (each 28px chip exactly 28px from the
      // next, i.e. touching) during the SFCC-236 Step 6 real-browser/Figma visual audit.
      justifyContent: 'space-between',
    },

    oneSize: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      // The non-interactive single-label footprint from the size-chip Figma component set's
      // other Type — no matching width-scale token for 65px; height reuses the same
      // --zimm-scale-700 (28px) the ZimmSizeChip atom's own `chip` part uses, since it is the
      // same row height as the interactive variant.
      // audit-allow: 65px — no foundation width token exists for this exact non-interactive
      // label size
      width: '65px',
      height: 'var(--zimm-scale-700)',
      // No token named for this specific "primary/dark border" purpose exists in the
      // `border` alias tier (see foundation/colour.ts) — only default/secondary/focus/
      // forms/error. The value here is confirmed directly against Figma node
      // 40003066:34866 ("Type=One Size") and matches `border.focus` (grey/900) exactly, but
      // the token name is semantically wrong for a static, non-focus box — the same
      // reuse-for-the-wrong-purpose gap already accepted in zimmSizeChip.css.ts's own
      // resolveBorderColour (Selected reuses border.focus to mean "selected") and
      // zimmSlideIndicator.css.ts's active dot. Pending a real foundation token from the
      // UI designer.
      border: 'var(--zimm-border-width-default) solid var(--zimm-color-border-focus)',
      // Figma's own citation for this text node is `size: default/caption`, not a button
      // style — matches this codebase's `caption` textStyle line for line (fontFamily/
      // fontSize/fontWeight/lineHeight/letterSpacing all identical to `buttonSm`) except
      // `caption` has no `textTransform`, correctly: this is a static label, not a button.
      textStyle: 'caption',
      color: 'var(--zimm-color-text-default)',
    },
  }),
};

